code.source:
#include <iostream>
using namespace std;

int main() {
    int fish = 3;
    int* p = &fish;
    cout << *p << endl;
    *p = 10;
    cout << fish << endl;
    return 0;
}

#include <iostream>
using namespace std;

void swap_values(int* a, int* b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int main() {
    int x = 1, y = 2;
    swap_values(&x, &y);
    cout << x << " " << y << endl;
    return 0;
}

